import db from "@/lib/db";
import type { Product } from "@/types/product";

type CatalogRow = {
  model_id: number;
  name: string;
  category: string | null;
  description: string | null;
  image: string | null;
  old_price: number | null;
  variant_id: number | null;
  sale_price: number | null;
  stock: number | null;
};

/**
 * کاتالوگ فروشگاه دقیقاً از همان دیتابیسی خوانده می‌شود که پنل مدیریت ویرایش می‌کند؛
 * بنابراین قیمت، تصویر، دسته‌بندی و موجودی همیشه مشترک هستند.
 */
export async function getStoreProducts(): Promise<Product[]> {
  const rows = db
    .prepare(
      `SELECT pm.id AS model_id, pm.name, pm.category, pm.description, pm.image, pm.old_price,
              pv.id AS variant_id, pv.sale_price, pv.stock
       FROM product_models pm
       LEFT JOIN product_variants pv ON pv.model_id = pm.id
       ORDER BY pm.id ASC, pv.id ASC`
    )
    .all() as CatalogRow[];

  return rows.map((row) => ({
    id: row.variant_id ?? row.model_id,
    variantId: row.variant_id ?? undefined,
    modelId: row.model_id,
    name: row.name,
    category: (row.category ?? "بهداشتی") as Product["category"],
    description: row.description ?? "",
    image: row.image && row.image.trim() !== "" ? row.image : "/file.svg",
    price: row.sale_price ?? undefined,
    oldPrice: row.old_price ?? undefined,
    stock: row.stock ?? 0,
  }));
}
